class Solution { string expression;int index=0;bool parse(){char ch=expression[index++];if(ch=='t')return true;if(ch=='f')return false;++index;if(ch=='!'){bool value=!parse();++index;return value;}bool value=ch=='&';while(true){bool next=parse();value=ch=='&'?value&&next:value||next;if(expression[index]==')'){++index;return value;}++index;}}public:bool parseBoolExpr(string input){expression=input;index=0;return parse();} };
